      const rows = [[L("लग्न कुण्डली (D1)", "Sign chart (D1)"), `${sn(x.sign)} ${dms(x.deg).slice(0, 6)} · ${L(`${ovn(rh1)} खाना`, `house ${rh1}`)} · ${H(REL[d.r1])}${x.retro && !["Rahu", "Ketu"].includes(p) ? L(" · वक्री", " · retrograde") : ""}${d.comb ? L(" · अस्त", " · combust") : ""}`], [L("के.पी. भाव चलित", "KP bhava chalit"), `${L(`${ovn(bh)} भाव`, `house ${bh}`)} · ${L("नक्षत्र", "star")} ${nk(x.nak)} (${pn(x.star)}) · ${L("उप", "sub")} ${pn(x.sub)} · ${L("कारक", "signifies")} ${hs(sigA(p))}`], [L("चंद्र कुण्डली", "Moon chart"), p === "Moon" ? L("स्वयं लग्न", "itself the ascendant") : L(`चंद्र से ${ovn(d.mh)} भाव`, `house ${d.mh} from the Moon`)], [L("नवांश (D9)", "Navamsa (D9)"), `${sn(d.d9)} · ${L(`${ovn(d.d9h)} भाव`, `house ${d.d9h}`)} · ${H(REL[d.r9])}${d.varg ? L(" · वर्गोत्तम", " · vargottama") : ""}`], [L("दशमांश (D10)", "Dashamsa (D10)"), `${sn(d.d10)} · ${L(`${ovn(d.d10h)} भाव`, `house ${d.d10h}`)}`]];
      const d9txt = d.varg ? L(`नवांश में भी यह ${sn(d.d9)} में है (<b>वर्गोत्तम</b>) — ${H(T.KARAKA[p]).split(",")[0]} के मामलों में यह ग्रह भीतर से बहुत भरोसेमंद है और अपने वादे पूरे करता है।`, `It is in ${sn(d.d9)} in the Navamsa too (<b>vargottama</b>) — inwardly very reliable in matters of ${H(T.KARAKA[p]).split(",")[0]}; it keeps its promises.`) : ["ex", "own"].includes(d.r9) ? L(`नवांश में ${sn(d.d9)} (${H(REL[d.r9])}) होने से इसका <b>भीतरी बल अच्छा</b> है — आयु बढ़ने के साथ इसके फल और निखरते हैं।`, `Being ${H(REL[d.r9])} in ${sn(d.d9)} in the Navamsa, its <b>inner strength is good</b> — its results improve with age.`) : ["en", "deb"].includes(d.r9) ? L(`नवांश में ${sn(d.d9)} (${H(REL[d.r9])}) — ${H(T.KARAKA[p]).split(",")[0]} से जुड़े फल बाहर से जितने दिखते हैं, भीतर से उतने स्थिर नहीं; इसके विषयों में धैर्य रखें।`, `${H(REL[d.r9])} (${sn(d.d9)}) in the Navamsa — results of ${H(T.KARAKA[p]).split(",")[0]} look better on the surface than they are inside; be patient with its matters.`) : L(`नवांश में ${sn(d.d9)} (स्वामी ${pn(KX.SIGN_LORD[d.d9 - 1])}, ${H(REL[d.r9])}) — भीतरी बल सामान्य है; ${d.d9h === 1 || d.d9h === 7 ? "विवाह के बाद इसका प्रभाव अधिक स्पष्ट होता है" : [6, 8, 12].includes(d.d9h) ? `नवांश के ${ov(d.d9h)} भाव में होने से इसके फल धैर्य माँगते हैं` : `नवांश के ${ov(d.d9h)} भाव में होने से ${H(T.EVT[d.d9h])} में इसका भीतरी सहयोग मिलता है`}।`, `In the Navamsa it is in ${sn(d.d9)} (lord ${KX.SIGN_LORD[d.d9 - 1]}, ${H(REL[d.r9])}) — average inner strength; ${d.d9h === 1 || d.d9h === 7 ? "its effect becomes clearer after marriage" : [6, 8, 12].includes(d.d9h) ? `in Navamsa house ${d.d9h} its results need patience` : `in Navamsa house ${d.d9h} it gives inner support to ${H(T.EVT[d.d9h])}`}.`);
      const d9marr = d.d9h === 7 ? L(` नवांश के सातवें भाव में होने से जीवनसाथी के स्वभाव पर इसका प्रभाव रहेगा (${H(T.P_SP[p]).split(",")[0]})।`, ` In the Navamsa 7th house it colours the partner's nature (${H(T.P_SP[p]).split(",")[0]}).`) : "";
